def seed_convergence(runs, window=20, tolerance=0.01, patience=3) -> dict:
    """按 seed 分组汇总逐回合 reward 的收敛判定，返回汇总报告。

    runs 须为长度至少 2 的 list：非 list 抛 TypeError，少于两项抛
    ValueError。每项须为键序恰为 seed、episode_results 的 dict：
    seed 为非 bool 的 int，episode_results（下称 E）须为 list；
    项本身或字段类型错抛 TypeError，键序错抛 ValueError。E 及
    window、tolerance、patience 的校验、异常与算法沿用
    convergence_report。先依输入序完整校验全部成员（含各 E 与三个
    参数），再按 seed 首次出现顺序分组、组内保持原序；任一 seed 少于
    两项或同 seed 的 E 长度不一均抛 ValueError，任一失败都不返回
    部分结果，且不修改输入。

    对各组按组内原序的每个 E 调用 convergence_report（window、
    tolerance、patience 相同）。返回键序为 stable、groups、
    problems：groups 按 seed 首次出现序排列，每项键序固定为
    seed、indices、reports、consistent、converged，indices 为该组
    各项在原 runs 中的零基索引升序 list，reports 为按组内原序排列
    的完整报告 list，consistent 表示各报告 converged 是否全同，
    converged 表示各报告 converged 是否全真；problems 按组序收集
    末两项任一为 False 的 seed，stable 当且仅当 problems 为空。
    重复调用及深拷贝逐值一致，仅用标准库，不引入命令行入口。
    """
    if not isinstance(runs, list):
        raise TypeError("runs must be a list")
    if len(runs) < 2:
        raise ValueError("runs must contain at least two entries")

    validated = []
    for index, item in enumerate(runs):
        if not isinstance(item, dict):
            raise TypeError(f"runs[{index}] must be a dict")
        if list(item) != ["seed", "episode_results"]:
            raise ValueError(
                f"runs[{index}] must have exactly the keys"
                " seed, episode_results"
            )
        seed = item["seed"]
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise TypeError(f"runs[{index}] seed must be a non-bool int")
        episode_results = item["episode_results"]
        if not isinstance(episode_results, list):
            raise TypeError(
                f"runs[{index}] episode_results must be a list"
            )
        _validate_convergence_args(
            episode_results, window, tolerance, patience
        )
        validated.append((seed, episode_results))

    seed_order = []
    indices_by_seed = {}
    results_by_seed = {}
    for index, (seed, episode_results) in enumerate(validated):
        if seed not in indices_by_seed:
            seed_order.append(seed)
            indices_by_seed[seed] = []
            results_by_seed[seed] = []
        indices_by_seed[seed].append(index)
        results_by_seed[seed].append(episode_results)

    for seed in seed_order:
        group_results = results_by_seed[seed]
        if len(indices_by_seed[seed]) < 2:
            raise ValueError(f"seed {seed} must have at least two runs")
        baseline_length = len(group_results[0])
        for episode_results in group_results[1:]:
            if len(episode_results) != baseline_length:
                raise ValueError(
                    f"all runs with seed {seed} must have"
                    " episode_results lists of equal length"
                )

    groups = []
    problems = []
    for seed in seed_order:
        reports = [
            convergence_report(
                episode_results,
                window=window,
                tolerance=tolerance,
                patience=patience,
            )
            for episode_results in results_by_seed[seed]
        ]
        converged_flags = [report["converged"] for report in reports]
        consistent = all(
            flag == converged_flags[0] for flag in converged_flags
        )
        all_converged = all(converged_flags)
        groups.append(
            {
                "seed": seed,
                "indices": indices_by_seed[seed],
                "reports": reports,
                "consistent": consistent,
                "converged": all_converged,
            }
        )
        if not consistent or not all_converged:
            problems.append(seed)

    return {
        "stable": not problems,
        "groups": groups,
        "problems": problems,
    }


